/// <summary>
/// MPJ_28395_Stock reservation - 25/07/2022
/// Contract class <c>METSalesOrderAutoReserveContract</c> to maintain all parameters required
/// </summary>
[   
    DataContract,
    SysOperationContractProcessingAttribute(classStr(METSalesOrderAutoReserveUIBuilder))
]
class METSalesOrderAutoReserveContract 
{
    METSalesOrderTypeID metSalesOrderTypeId;
    InventLocationId    inventLocationId;
    Days                metReserveDaysPriorShipDate;
    int                 tasks;
    List                itemIdList = new List(Types::String);
    METTaskGuid         batchRunGUID;
    
    // <summary>
    /// Parameter method which holds values of Metcash sales order type
    /// </summary>
    /// <param name = "_metSalesOrderTypeID">MET Sales order type Id</param>
    /// <returns>MET Sales order type Id</returns>
    
}

Method.Source:
[DataMemberAttribute('MetSalesOrderType')]
public MetSalesOrderTypeId parmMetSalesOrderTypeId(METSalesOrderTypeID _metSalesOrderTypeID =  metSalesOrderTypeId)
{
    metSalesOrderTypeId = _metSalesOrderTypeId;
    return metSalesOrderTypeId;    
}

/// <summary>
/// Parameter method which holds value of Warehouse
/// </summary>
/// <param name = "_inventLocationId">InventLocationId</param>
/// <returns>InventLocationId</returns>

[DataMemberAttribute('Warehouse')]
public InventLocationId parmInventLocationId(InventLocationId _inventLocationId =  inventLocationId)
{
    inventLocationId = _inventLocationId;
    return inventLocationId;
}

/// <summary>
/// Parameter method which holds Reserve days prior ship date
/// </summary>
/// <param name = "_metReserveDaysPriorShipDate">Reserve days prior ship date</param>
/// <returns>Reserve days prior ship date</returns>
 
[DataMemberAttribute('METReserveDaysPriorShipDate')]
public Days parmMETReserveDaysPriorShipDate(Days _metReserveDaysPriorShipDate =  metReserveDaysPriorShipDate)
{
    metReserveDaysPriorShipDate = _metReserveDaysPriorShipDate;
    return metReserveDaysPriorShipDate;
}

[DataMemberAttribute('ItemIdList'),
 SysOperationControlVisibilityAttribute(false),
 AifCollectionTypeAttribute(identifierStr(_ItemIdListList), Types::String)]
public List parmItemIdList(List _ItemIdIdList = itemIdList)
{
    itemIdList = _ItemIdIdList;
    return itemIdList;
}

/// <summary>
/// Parameter method which holds value of number of sub tasks
/// </summary>
/// <param name = "_tasks">Sub tasks</param>
/// <returns>Number of sub tasks</returns>

[
    DataMemberAttribute('NumberofTasks'),
    SysOperationLabelAttribute(literalstr("Tasks")),
    SysOperationHelpText(literalstr("Specify number of tasks to run the batch job")),
    SysOperationDisplayOrderAttribute('2')
]
public int parmTasks(int _tasks = tasks)
{
    tasks = _tasks;
    return tasks;
}

/// <summary>
/// Parameter method which holds values of Batch run GUID
/// </summary>
/// <param name = "_batchRunGUID">batchRunGUID</param>
/// <returns>batchRunGUID</returns>

[DataMemberAttribute('BatchRunGUID'),
 SysOperationControlVisibilityAttribute(false)]
public METTaskGuid parmBatchRunGUID(METTaskGuid _batchRunGUID =  batchRunGUID)
{
    batchRunGUID = _batchRunGUID;
    return batchRunGUID;
}
